+        embeddedChannel.flushOutbound();
+
+        FullHttpRequest fullHttpRequest = embeddedChannel.readOutbound();
+        Assert.assertArrayEquals(dnsReq, ByteBufUtil.getBytes(fullHttpRequest.content()));
+
